# SCALP_V5 — same shape as HA
E(f"{BACKEND}/scalpv5/backtest_scalpv5_runner.py",
  ("replace", '    max_profit = abs(float(cfg.get("max_profit", 0) or 0))\n',
   '    max_profit = abs(float(cfg.get("max_profit", 0) or 0))\n' + IMPORT +
   "    _comp = _LotComp(cfg, date_from, lots)\n"),
  ("replace", "    for di, d in enumerate(sim_days, start=1):\n",
   "    for di, d in enumerate(sim_days, start=1):\n"
   "        if _comp.on:   # ── LOT_COMP_20260924 ── today's qty; the RUN-cumulative ₹ cap below\n"
   "            qty = _comp.lots(d) * LOT_SIZE   #    is compared in base-lot units, not rescaled\n"),
  # V5's max_loss/max_profit is a run-cumulative gross cap (never reset), so a
  # per-day rescale would mix tiers. Instead each trade's gross is booked into
  # the running total in BASE-lot units (÷ today's ratio): the cap fires
  # exactly where the flat run's would — the strategy at base size would have
  # been stopped here. OFF ⇒ ratio 1 ⇒ byte-identical.
  ("replace_all:2", "realised_running += (open_trade.gross or 0.0)\n",
   "realised_running += (open_trade.gross or 0.0) / _comp.mult(d)   # ── LOT_COMP_20260924 ── base-lot units\n"))

