# ═══════════════════════════ machinery ═══════════════════════════════════

def die(msg):
    print(f"\nABORT: {msg}")
    sys.exit(1)


def read(rel):
    with open(os.path.join(ROOT, rel), encoding="utf-8") as f:
        return f.read()


def apply_ops(text, ops, rel):
    for kind, old, new in ops:
        if kind == "replace":
            n = text.count(old)
            if n != 1:
                die(f"{rel}: anchor found {n}× (need 1): {old.splitlines()[0][:90]!r}")
            text = text.replace(old, new)
        elif kind.startswith("replace_all:"):
            want = int(kind.split(":")[1])
            n = text.count(old)
            if n != want:
                die(f"{rel}: anchor found {n}× (need {want}): {old[:90]!r}")
            text = text.replace(old, new)
        elif kind == "after_line":
            lines = text.split("\n")
            hits = [i for i, l in enumerate(lines) if old in l]
            if len(hits) != 1:
                die(f"{rel}: line anchor found {len(hits)}× (need 1): {old[:90]!r}")
            lines.insert(hits[0] + 1, new.rstrip("\n"))
            text = "\n".join(lines)
        else:
            die(f"bad op kind {kind}")
    return text


def git_dirty(rels):
    try:
        out = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=ROOT,
                             capture_output=True, text=True, timeout=30).stdout
    except Exception:
        return []
    return [l for l in out.splitlines() if l.strip() and not l.startswith("??")]   # untracked ≠ modified


def main():
    print(f"── {FENCE} ── root {ROOT}")
    if not os.path.isdir(os.path.join(ROOT, BACKEND)) or not os.path.isdir(os.path.join(ROOT, FRONTEND)):
        die("run from the scalp-app repo root (backend/ and frontend/ not found)")

    targets = list(EDITS.keys())
    payload_paths = list(PAYLOADS_B64.keys())

    # 1. fence presence → already applied
    for rel in targets:
        if not os.path.exists(os.path.join(ROOT, rel)):
            die(f"missing target {rel}")
        if FENCE in read(rel):
            die(f"{FENCE} already present in {rel} — nothing to do")
    for rel in payload_paths:
        if os.path.exists(os.path.join(ROOT, rel)):
            die(f"{rel} already exists — mixed state; git checkout / remove it and re-run ONLY this script")

    # 2. prerequisites
    for rel, fence in PREREQ.items():
        if fence not in read(rel):
            die(f"prerequisite {fence} not found in {rel}")
    print(f"   prerequisites ok ({len(PREREQ)})")

    # 3. working-copy stop sign
    dirty = git_dirty(targets)
    if dirty:
        print("   git status shows uncommitted changes on targets:")
        for l in dirty:
            print("     ", l)
        if not ALLOW_DIRTY:
            die("an `M` on a target is a stop sign (ORB_RECONCILE scar); commit/stash or re-run with --allow-dirty")
        print("   --allow-dirty: continuing")

    # 4. apply in memory
    staged = {}
    for rel, ops in EDITS.items():
        staged[rel] = apply_ops(read(rel), ops, rel)
    for rel, b64 in PAYLOADS_B64.items():
        staged[rel] = base64.b64decode(b64).decode("utf-8")
    print(f"   {len(EDITS)} files edited in memory, {len(PAYLOADS_B64)} payloads")

    # 5. py_compile gate before ANY write
    tmp = tempfile.mkdtemp(prefix="lot_comp_gate_")
    for rel, txt in staged.items():
        if rel.endswith(".py"):
            p = os.path.join(tmp, os.path.basename(rel))
            with open(p, "w", encoding="utf-8") as f:
                f.write(txt)
            try:
                py_compile.compile(p, doraise=True)
            except py_compile.PyCompileError as e:
                die(f"py_compile failed for {rel}: {e}")
    shutil.rmtree(tmp, ignore_errors=True)
    print("   py_compile gate ok")

    # 6. staged all-or-nothing writes with backups (+ desktop mirrors when present)
    written = []
    for rel, txt in staged.items():
        abs_ = os.path.join(ROOT, rel)
        if os.path.exists(abs_):
            shutil.copy2(abs_, abs_ + f".bak-{FENCE}")
        os.makedirs(os.path.dirname(abs_), exist_ok=True)
        with open(abs_, "w", encoding="utf-8") as f:
            f.write(txt)
        written.append(rel)
        for src_root, dst_root in ((BACKEND, DESKTOP_BACKEND), (FRONTEND, DESKTOP_FRONTEND)):
            if rel.startswith(src_root):
                mirror = os.path.join(ROOT, dst_root + rel[len(src_root):])
                if os.path.isdir(os.path.dirname(mirror)) or os.path.isdir(os.path.join(ROOT, dst_root)):
                    os.makedirs(os.path.dirname(mirror), exist_ok=True)
                    with open(mirror, "w", encoding="utf-8") as f:
                        f.write(txt)
    print(f"   wrote {len(written)} files (backups: .bak-{FENCE})")
    with open(os.path.join(ROOT, f".{FENCE}.done"), "w") as f:
        f.write("applied\n")

    if SKIP_TESTS:
        print("   --skip-tests: done")
        return

    # 7. tests
    env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "backend"), SCALP_LOT_SIZE_OFFLINE="1")
    suites = [
        "app/backtest/engine/test_lot_compounding.py",
        "app/backtest/engine/test_lot_comp_runners.py",
        "app/backtest/orb/test_orb_runner_sim.py",
        "app/backtest/brk/test_brk_runner_sim.py",
        "app/backtest/stfc/test_stfc_runner_sim.py",
        "app/backtest/fvg/test_fvg_runner_sim.py",
        "app/backtest/tma/test_tma_v2_dte_lots.py",
        "app/backtest/tsg/test_tsg_runner.py",
        "app/backtest/orv/test_orv_runner_sim.py",
        "app/backtest/vet/test_vet_daily_cap.py",
        "app/backtest/vet/test_vet_hedge_leg.py",
    ]
    failed = []
    for s in suites:
        r = subprocess.run([sys.executable, s], cwd=os.path.join(ROOT, "backend"),
                           env=env, capture_output=True, text=True, timeout=1800)
        tail = (r.stdout.strip().splitlines() or [""])[-1]
        print(f"   {'ok  ' if r.returncode == 0 else 'FAIL'} {s}  — {tail[:100]}")
        if r.returncode != 0:
            failed.append(s)
            print((r.stdout + r.stderr)[-3000:])
    # esbuild parse of the four JSX files + the helper (syntax gate; the real
    # build is `./desktop/build-scalp.sh both`)
    esb = (os.environ.get("ESBUILD") or
           (os.path.join(ROOT, "frontend", "node_modules", ".bin", "esbuild")
            if os.path.exists(os.path.join(ROOT, "frontend", "node_modules", ".bin", "esbuild")) else None) or
           (shutil.which("esbuild")) or ("npx" if shutil.which("npx") else None))
    if esb:
        for rel in [f"{FRONTEND}/Backtest.jsx", f"{FRONTEND}/backtest/RunComparison.jsx",
                    f"{FRONTEND}/backtest/BacktestQueue.jsx", f"{FRONTEND}/backtest/SweepBuilder.jsx",
                    f"{FRONTEND}/backtest/Portfolio.jsx", f"{FRONTEND}/backtest/lotCompounding.js"]:
            cmd = ([esb, "--yes", "esbuild"] if esb == "npx" else [esb])
            r = subprocess.run(cmd + [rel, "--loader:.jsx=jsx", "--loader:.js=jsx",
                                "--log-level=error", "--outfile=/dev/null"],
                               cwd=ROOT, capture_output=True, text=True, timeout=300)
            print(f"   {'ok  ' if r.returncode == 0 else 'FAIL'} esbuild {rel}")
            if r.returncode != 0:
                failed.append(rel)
                print(r.stderr[-2000:])
    else:
        print("   (esbuild not found — skipping JSX parse; run ./desktop/build-scalp.sh both)")

    if failed:
        print("\n   FAILURES — rolling back to the .bak files:")
        for rel in written:
            abs_ = os.path.join(ROOT, rel)
            bak = abs_ + f".bak-{FENCE}"
            if os.path.exists(bak):
                shutil.move(bak, abs_)
            else:
                os.remove(abs_)
        try:
            os.remove(os.path.join(ROOT, f".{FENCE}.done"))
        except OSError:
            pass
        die("tests failed; working copy restored (desktop mirrors, if any, were NOT rolled back — rerun build-scalp.sh both after fixing)")
    print(f"\n── {FENCE} applied. Next: ./desktop/build-scalp.sh both ──")


